// HTTP Request devuelve el array como 1 item de n8n — lo expandimos
const raw = $input.all();
let orders = [];
if (raw.length === 1 && Array.isArray(raw[0].json)) {
  orders = raw[0].json.map(o => ({ json: o }));
} else {
  orders = raw;
}
const limited = orders.slice(0, 3);
console.log(`Demo: procesando ${limited.length} de ${orders.length} órdenes confirmadas`);
return limited;

// Retrieve items from this node's input
const items = $input.all().map(i => i.json);

// Grab order context from the SplitInBatches node
const orderNode = $('Procesar Cada Orden').first().json;
const orderId = orderNode.id || 'N/A';
const customerNombre = orderNode.customer_nombre || 'N/A';
const localidad = orderNode.localidad || 'N/A';
const fecha = orderNode.fecha || new Date().toISOString().split('T')[0];
const totalOrder = orderNode.total || 0;

// Format ARS currency: 208320.00 → $ 208.320,00
const formatARS = (num) => {
  const n = parseFloat(num) || 0;
  const parts = n.toFixed(2).split('.');
  const intPart = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, '.');
  return `$ ${intPart},${parts[1]}`;
};

// Build items table rows
const itemRows = items.map(it => {
  const subtotal = (it.cantidad || 0) * (it.precio_unitario || 0);
  return `
    <tr>
      <td>${it.sku || ''}</td>
      <td>${it.nombre || ''}</td>
      <td style="text-align:center">${it.cantidad || 0}</td>
      <td style="text-align:right">${formatARS(it.precio_unitario)}</td>
      <td style="text-align:right">${formatARS(subtotal)}</td>
    </tr>`;
}).join('');

// Generate remito number with zero-padding
const remitoNum = String(orderId).padStart(6, '0');

const html = `<!DOCTYPE html>
<html lang="es">
<head>
  <meta charset="UTF-8">
  <title>Remito N\u00b0 ${remitoNum} - Golden Harvest S.A.</title>
  <style>
    body { font-family: Arial, sans-serif; font-size: 12px; color: #222; margin: 40px; }
    .header { display: flex; justify-content: space-between; align-items: flex-start; border-bottom: 3px solid #4a7c2f; padding-bottom: 16px; margin-bottom: 24px; }
    .company-name { font-size: 22px; font-weight: bold; color: #4a7c2f; }
    .company-info { font-size: 11px; color: #555; margin-top: 4px; }
    .doc-title { font-size: 20px; font-weight: bold; text-align: right; }
    .doc-meta { font-size: 11px; text-align: right; color: #555; margin-top: 4px; }
    .section { margin-bottom: 20px; }
    .section-title { font-weight: bold; background: #f0f5eb; padding: 4px 8px; border-left: 4px solid #4a7c2f; margin-bottom: 8px; }
    .info-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 4px 24px; }
    .info-row { display: flex; gap: 8px; }
    .info-label { color: #555; min-width: 120px; }
    table { width: 100%; border-collapse: collapse; margin-top: 8px; }
    thead tr { background: #4a7c2f; color: white; }
    th { padding: 6px 8px; text-align: left; font-size: 11px; }
    tbody tr:nth-child(even) { background: #f9f9f9; }
    td { padding: 5px 8px; border-bottom: 1px solid #e0e0e0; }
    .total-row { font-weight: bold; font-size: 13px; background: #f0f5eb; }
    .firma-section { display: flex; justify-content: space-between; margin-top: 60px; }
    .firma-box { text-align: center; width: 200px; }
    .firma-line { border-top: 1px solid #333; margin-bottom: 6px; }
    .footer { margin-top: 40px; text-align: center; font-size: 10px; color: #999; border-top: 1px solid #ddd; padding-top: 8px; }
  </style>
</head>
<body>
  <div class="header">
    <div>
      <div class="company-name">Golden Harvest S.A.</div>
      <div class="company-info">
        CUIT: 30-12345678-9<br>
        Ruta Provincial 143 Km 12, San Rafael, Mendoza<br>
        Tel: (0260) 555-0100 | info@goldenharvest.com.ar
      </div>
    </div>
    <div>
      <div class="doc-title">REMITO N\u00b0 ${remitoNum}</div>
      <div class="doc-meta">
        Fecha: ${fecha}<br>
        Tipo: X (sin discriminaci\u00f3n de IVA)
      </div>
    </div>
  </div>

  <div class="section">
    <div class="section-title">DATOS DEL DESTINATARIO</div>
    <div class="info-grid">
      <div class="info-row"><span class="info-label">Raz\u00f3n Social:</span><strong>${customerNombre}</strong></div>
      <div class="info-row"><span class="info-label">Localidad:</span>${localidad}</div>
    </div>
  </div>

  <div class="section">
    <div class="section-title">DETALLE DE MERCANC\u00cdA</div>
    <table>
      <thead>
        <tr>
          <th>SKU</th>
          <th>Producto</th>
          <th style="text-align:center">Cantidad</th>
          <th style="text-align:right">Precio Unit.</th>
          <th style="text-align:right">Subtotal</th>
        </tr>
      </thead>
      <tbody>
        ${itemRows}
        <tr class="total-row">
          <td colspan="4" style="text-align:right">TOTAL:</td>
          <td style="text-align:right">${formatARS(totalOrder)}</td>
        </tr>
      </tbody>
    </table>
  </div>

  <div class="firma-section">
    <div class="firma-box">
      <div class="firma-line"></div>
      <div>Firma y Sello Emisor</div>
      <div style="font-size:10px;color:#666">Golden Harvest S.A.</div>
    </div>
    <div class="firma-box">
      <div class="firma-line"></div>
      <div>Firma y Aclaraci\u00f3n Receptor</div>
      <div style="font-size:10px;color:#666">Aclaraci\u00f3n / DNI</div>
    </div>
    <div class="firma-box">
      <div class="firma-line"></div>
      <div>Transportista</div>
      <div style="font-size:10px;color:#666">Firma y Sello</div>
    </div>
  </div>

  <div class="footer">
    Documento no v\u00e1lido como factura \u2014 Remito interno de despacho | Golden Harvest S.A. \u00a9 2026
  </div>
</body>
</html>`;

// Log summary to console (not full HTML)
console.log(`[REMITO] Orden #${orderId} | Cliente: ${customerNombre} | Localidad: ${localidad} | Total: ${formatARS(totalOrder)} | Items: ${items.length}`);

return [{
  json: {
    order_id: orderId,
    customer_nombre: customerNombre,
    localidad: localidad,
    fecha: fecha,
    total: totalOrder,
    total_ars: formatARS(totalOrder),
    items_count: items.length,
    remito_numero: remitoNum,
    remito_html: html
  }
}];
